        path: spec.language.save_as.to_string(),
        content: format!("{}\n", spec.template.code.trim_end()),
    })
}

fn requested_rewrite(task: &str, artifact: &WorkspaceArtifact) -> Option<WorkspaceRewrite> {
    if let Some(program) = explicit_substitution_query(task) {
        return Some(WorkspaceRewrite {
            target: artifact.path.clone(),
            program,
        });
    }
    if task.contains('?') || task.contains('？') {
        return None;
    }
    let quoted = quoted_segments(task);
    let pairs = match quoted.as_slice() {
        [new] => vec![(last_string_literal(&artifact.content)?, new.clone())],
        values if !values.is_empty() && values.len() % 2 == 0 => values
            .as_chunks::<2>()
            .0
            .iter()
            .map(|[old, new]| (old.clone(), new.clone()))
            .collect(),
        _ => return None,
    };
    if pairs.iter().any(|(old, new)| old == new) {
        return None;
    }
    let single_substitution = pairs.len() == 1;
    let rules = pairs
        .into_iter()
        .map(|(old, new)| {
            let rule = RewriteRule::new(old.clone(), new);
            if single_substitution || old.is_empty() {
                rule.terminal()
            } else {
                rule
            }
        })
        .collect();
    Some(WorkspaceRewrite {
        target: artifact.path.clone(),
        program: RewriteProgram::new(rules, MAX_REWRITE_STEPS),
    })
}

/// Accept the meta-language query itself as the request.
///
/// Prose with quoted operands only ever composes old/new pairs, so this is the
/// only route to link-cli's `()` creation and deletion shorthands and to
/// terminal rules. The whole turn must be the query: requiring that keeps the
/// route unambiguous against ordinary prose that merely contains parentheses.
pub(super) fn explicit_substitution_query(task: &str) -> Option<RewriteProgram> {
    let trimmed = task.trim();
    if !trimmed.starts_with('(') {
        return None;
    }
    let program = parse_substitution_query(trimmed, MAX_REWRITE_STEPS).ok()?;
    (!program.rules.is_empty()).then_some(program)
}

fn latest_workspace_artifact(messages: &[ChatMessage]) -> Option<WorkspaceArtifact> {
    messages
        .iter()
        .rev()
        .flat_map(|message| message.tool_calls.iter().rev())
        .find_map(|call| {
            if tool_capability(&call.function.name) != Some(Capability::Write) {
                return None;
            }
            let arguments: Value = serde_json::from_str(&call.function.arguments).ok()?;
            let path = argument_string(&arguments, &["path", "filePath", "file_path"])?;
            let content = argument_string(&arguments, &["content"])?;
            Some(WorkspaceArtifact {
                path: path.to_owned(),
                content: content.to_owned(),
            })
        })
}

/// The latest receipt associated with this exact command in the supplied request window.
pub(super) fn result_for_command(messages: &[ChatMessage], command: &str) -> Option<String> {
    messages.iter().enumerate().rev().find_map(|(index, message)| {
        if !message.role.eq_ignore_ascii_case("tool") {
            return None;
        }
        let id = message.tool_call_id.as_deref()?;
        let call = messages[..index]
            .iter()
            .rev()
            .flat_map(|prior| prior.tool_calls.iter().rev())
            .find(|call| call.id == id)?;
        (tool_capability(&call.function.name) == Some(Capability::Run)
            && super::tool_result::command_argument(&call.function.arguments).as_deref()
                == Some(command))
            .then(|| message.content.plain_text())
    })
}

pub(super) fn latest_result(messages: &[ChatMessage], capability: Capability) -> Option<String> {
    messages
        .iter()
        .enumerate()
        .rev()
        .find_map(|(index, message)| {
            if !message.role.eq_ignore_ascii_case("tool") {
                return None;
            }
            let call_id = message.tool_call_id.as_ref()?;
            let call = messages[..index]
                .iter()
                .flat_map(|prior| prior.tool_calls.iter())
                .find(|call| &call.id == call_id)?;
            (tool_capability(&call.function.name) == Some(capability))
                .then(|| message.content.plain_text())
        })
}

/// Decode decorated source emitted by coding-agent read tools. `OpenCode` wraps
/// numbered lines in `<content>` while Agent wraps pipe-numbered lines in
/// `<file>`. Other CLIs return raw contents, which pass through byte-for-byte.
pub(super) fn source_from_read_result(result: &str) -> String {
    if let Some(decoded) = source_from_agent_read_result(result) {
        return decoded;
    }
    let Some((_, after_open)) = result.split_once("<content>\n") else {
        return result.to_owned();
    };
    let Some((content, _)) = after_open.rsplit_once("\n</content>") else {
        return result.to_owned();
    };
    let mut decoded = String::new();
    for line in content.lines() {
        if line.starts_with("(End of file - total ") {
            break;
        }
        let source_line = line
            .split_once(": ")
            .filter(|(number, _)| number.chars().all(|character| character.is_ascii_digit()))
            .map_or(line, |(_, source)| source);
        decoded.push_str(source_line);
        decoded.push('\n');
    }
    while decoded.ends_with("\n\n") {
        decoded.pop();
    }
    decoded
}

pub(super) fn source_from_agent_read_result(result: &str) -> Option<String> {
    let after_open = result.strip_prefix("<file>\n")?;
    let (numbered, footer) = after_open.rsplit_once("\n\n(End of file - total ")?;
    if !footer.ends_with("</file>") {
        return None;
    }
    numbered
        .lines()
        .map(|line| {
            let (number, source) = line.split_once("| ")?;
            number
                .chars()
                .all(|character| character.is_ascii_digit())
                .then_some(source)
        })
        .collect::<Option<Vec<_>>>()
        .map(|lines| lines.join("\n"))
}

fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

fn argument_string<'a>(value: &'a Value, keys: &[&str]) -> Option<&'a str> {
    keys.iter().find_map(|key| value.get(key)?.as_str())
}

fn last_string_literal(source: &str) -> Option<String> {
    quoted_segments(source).pop()
}

/// Write one `name value` link, quoted the way Links Notation quotes.
///
/// The trace is published as the meta-language representation of the request,
/// so it has to be readable by a Links Notation reader, not merely look like
/// one. Notation escapes a quote by *doubling* it and picks a delimiter the
/// value does not already contain; a backslash escape leaves the quote visible
/// to the reader, which ends the string early and turns a code fragment's `(`
/// into an unclosed group. Delegating to the codec's own escaper is what keeps
/// the two definitions from drifting apart again.
fn link_field(out: &mut String, indent: usize, name: &str, value: &str) {
    let _ = writeln!(
        out,
        "{}{name} {}",
        " ".repeat(indent),
        escape_reference(value)
    );
}

