    let lexicon = seed::lexicon();
    if !lexicon.mentions_role(seed::ROLE_FILE_WRITE_ACTION_CUE, &normalized)
        && !lexicon.mentions_role(seed::ROLE_PROGRAM_REQUEST, &normalized)
