        RustItemKind::Test
    } else if lexicon
        .first_role_match(seed::ROLE_PROGRAM_KIND, &normalized)
        .is_some_and(|meaning| meaning.slug == "function")
    {
        RustItemKind::Function
    } else {
        return None;
    };
