                    "coding_source_function_division",
                    &[
                        ("{visibility}", if public { "pub " } else { "" }),
                        ("{name}", &name),
                        ("{divisor}", divisor),
                    ],
                )?
            } else if lexicon.mentions_role(seed::ROLE_CODING_RETURN_ACTION, &normalized) {
                let value = numbers.last()?;
