                numbers.get(2),
                lexicon
                    .first_role_match(seed::ROLE_ARITHMETIC_OPERATOR_WORD, &normalized)
                    .and_then(|meaning| {
                        meaning
                            .words()
                            .find(|surface| !surface.chars().any(char::is_alphabetic))
                    }),
            ) {
